// frontend/src/admin/components/VisitorStats.jsx
// ============================================================
//  ✅ نسخه‌ی نهایی v3
//  - تمیز و متمرکز (بدون جدول آخرین بازدیدکنندگان)
//  - قیف تبدیل (Funnel): از صفحه اصلی تا پرداخت
//  - بازدیدکننده یکتا (نه کلیک)
//  - صفحات پربازدید
//  - heartbeat داخلی
// ============================================================

import { useState, useEffect, useRef } from 'react';
import axios from '../axiosConfig';

const fmt = (n) => Math.round(n || 0).toLocaleString('fa-IR');

const formatDay = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  const days = ['یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'];
  return days[d.getDay()];
};

const formatShortDate = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return d.toLocaleDateString('fa-IR', { month: 'short', day: 'numeric' });
};

// ============================================================
//  کارت آمار
// ============================================================
function StatCard({ icon, label, value, sub, variant }) {
  const styles = {
    online: {
      bg: 'bg-accent-50 dark:bg-accent-500/15 border-accent-200 dark:border-accent-500/30',
      value: 'text-accent-700 dark:text-accent-300',
      sub: 'text-accent-600 dark:text-accent-400',
    },
    today: {
      bg: 'bg-brand-50 dark:bg-brand-500/15 border-brand-200 dark:border-brand-500/30',
      value: 'text-brand-700 dark:text-brand-300',
      sub: 'text-brand-600 dark:text-brand-400',
    },
    week: {
      bg: 'bg-paper-50 dark:bg-ink-800 border-ink-200 dark:border-dark-700',
      value: 'text-ink-800 dark:text-cream-100',
      sub: 'text-ink-400 dark:text-cream-500',
    },
    month: {
      bg: 'bg-ink-900 dark:bg-ink-950 border-ink-700 text-cream-100',
      value: 'text-cream-50',
      sub: 'text-cream-400',
    },
  };
  const s = styles[variant] || styles.week;

  return (
    <div className={`${s.bg} border rounded-3xl p-3 sm:p-4 shadow-soft hover:shadow-lifted transition-all relative overflow-hidden`}>
      {variant === 'online' && (
        <div className="absolute top-2 right-2">
          <span className="w-2 h-2 rounded-full bg-accent-500 animate-pulse block" aria-hidden="true" />
        </div>
      )}
      <div className="flex items-center justify-between mb-2">
        <span className="text-lg sm:text-xl" aria-hidden="true">{icon}</span>
        <span className="text-[10px] sm:text-[11px] font-black text-right opacity-80">{label}</span>
      </div>
      <div className={`text-xl sm:text-2xl font-display font-black tracking-tight font-num tabular-nums ${s.value}`}>
        {value}
      </div>
      {sub && <div className={`text-[10px] mt-1 ${s.sub} truncate font-bold`}>{sub}</div>}
    </div>
  );
}

// ============================================================
//  قیف تبدیل (Funnel)
// ============================================================
function ConversionFunnel({ stages }) {
  if (!stages || stages.length === 0) {
    return (
      <div className="text-center text-sm text-ink-400 dark:text-cream-500 py-6">
        <div className="text-3xl mb-2 opacity-50">📊</div>
        <div className="text-xs font-bold">داده‌ای برای نمایش نیست</div>
      </div>
    );
  }

  const maxCount = Math.max(...stages.map((s) => s.count), 1);

  return (
    <div className="space-y-3">
      {stages.map((stage, i) => {
        const widthPct = (stage.count / maxCount) * 100;
        const isLast = i === stages.length - 1;
        const prevStage = i > 0 ? stages[i - 1] : null;
        const dropOff = prevStage && prevStage.count > 0
          ? prevStage.count - stage.count
          : 0;

        return (
          <div key={stage.key}>
            <div className="flex items-center justify-between mb-1.5">
              <div className="flex items-center gap-2">
                <span className="text-lg" aria-hidden="true">{stage.icon}</span>
                <span className="font-black text-sm text-ink-800 dark:text-cream-100">
                  {stage.label}
                </span>
              </div>
              <div className="flex items-center gap-2">
                <span className="font-display font-black text-base text-ink-800 dark:text-cream-100 font-num tabular-nums">
                  {fmt(stage.count)}
                </span>
                <span className="text-[10px] font-bold text-ink-500 dark:text-cream-400 font-num">
                  نفر
                </span>
              </div>
            </div>

            {/* نوار پیشرفت */}
            <div className="relative h-8 bg-paper-100 dark:bg-ink-700 rounded-xl overflow-hidden">
              <div
                className={`h-full rounded-xl transition-all duration-700 flex items-center px-3 ${
                  i === 0 ? 'bg-brand-gradient'
                  : i === 1 ? 'bg-brand-500'
                  : i === 2 ? 'bg-accent-500'
                  : 'bg-accent-600'
                }`}
                style={{ width: `${Math.max(widthPct, 2)}%` }}
              >
                {widthPct > 15 && (
                  <span className="text-[10px] font-black text-white font-num">
                    {stage.conversion_rate}٪
                  </span>
                )}
              </div>
            </div>

            {/* نرخ تبدیل و ریزش */}
            {!isLast && i > 0 && dropOff > 0 && (
              <div className="flex items-center gap-1 mt-1 text-[10px] text-rose-600 dark:text-rose-400 font-bold">
                <span aria-hidden="true">▼</span>
                <span className="font-num">{fmt(dropOff)} نفر منصرف شدند</span>
              </div>
            )}
            {isLast && stage.count > 0 && (
              <div className="flex items-center gap-1 mt-1 text-[10px] text-accent-600 dark:text-accent-400 font-bold">
                <span aria-hidden="true">✓</span>
                <span>مرحله نهایی خرید</span>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ============================================================
//  نمودار ۷ روز
// ============================================================
function WeeklyChart({ data }) {
  if (!data || data.length === 0) {
    return (
      <div className="text-center text-sm text-ink-400 dark:text-cream-500 py-6">
        <div className="text-3xl mb-2 opacity-50">📊</div>
        <div className="text-xs font-bold">داده‌ای نیست</div>
      </div>
    );
  }

  const maxVal = Math.max(...data.map((d) => d.total), 1);

  return (
    <div className="space-y-2">
      <div className="flex items-end gap-1.5 sm:gap-2 h-28 sm:h-32">
        {data.map((day, i) => {
          const totalH = (day.total / maxVal) * 100;
          const newH = day.total > 0 ? (day.new / day.total) * totalH : 0;
          const returnH = day.total > 0 ? (day.returning / day.total) * totalH : 0;

          return (
            <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
              <div className="absolute -top-7 opacity-0 group-hover:opacity-100 transition pointer-events-none bg-ink-900 text-cream-50 text-[10px] px-2 py-1 rounded-lg whitespace-nowrap z-10 font-num">
                {fmt(day.total)} نفر
              </div>
              <div className="w-full flex flex-col-reverse rounded-t-lg overflow-hidden" style={{ height: `${totalH}%`, minHeight: day.total > 0 ? '4px' : '0' }}>
                <div className="bg-brand-500 transition-all duration-500" style={{ height: `${newH}%` }} title={`جدید: ${fmt(day.new)}`} />
                <div className="bg-accent-400 transition-all duration-500" style={{ height: `${returnH}%` }} title={`بازگشتی: ${fmt(day.returning)}`} />
              </div>
              <span className="text-[9px] text-ink-500 dark:text-cream-400 mt-1.5 font-bold">
                {formatDay(day.date)}
              </span>
            </div>
          );
        })}
      </div>
      <div className="flex gap-4 justify-center text-[10px] font-bold">
        <div className="flex items-center gap-1.5">
          <div className="w-2.5 h-2.5 bg-brand-500 rounded"></div>
          <span className="text-ink-600 dark:text-cream-300">جدید</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-2.5 h-2.5 bg-accent-400 rounded"></div>
          <span className="text-ink-600 dark:text-cream-300">بازگشتی</span>
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function VisitorStats() {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const heartbeatRef = useRef(null);

  const fetchStats = () => {
    axios.get('/admin/dashboard/visitors')
      .then((res) => { setStats(res.data); setLoading(false); })
      .catch(() => { setLoading(false); });
  };

  useEffect(() => {
    fetchStats();
    const interval = setInterval(fetchStats, 30000);

    // heartbeat — با localStorage (یک نفر = یک کلید)
    const VISITOR_KEY = 'vs_key';
    let visitorKey = null;
    try {
      visitorKey = localStorage.getItem(VISITOR_KEY);
      if (!visitorKey) {
        visitorKey = 'vs_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 12);
        localStorage.setItem(VISITOR_KEY, visitorKey);
      }
    } catch {
      visitorKey = 'vs_temp_' + Math.random().toString(36).substr(2, 12);
    }

    const sendHeartbeat = () => {
      const page = window.location.pathname + window.location.search;
      const params = new URLSearchParams({ page, vs_key: visitorKey });
      axios.get(`/api/heartbeat?${params.toString()}`).catch(() => {});
    };
    sendHeartbeat();
    heartbeatRef.current = setInterval(sendHeartbeat, 60000);

    return () => {
      clearInterval(interval);
      if (heartbeatRef.current) clearInterval(heartbeatRef.current);
    };
  }, []);

  if (loading) {
    return (
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft p-4">
        <div className="animate-pulse">
          <div className="h-5 w-32 bg-paper-200 dark:bg-ink-700 rounded mb-4"></div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {[1,2,3,4].map((i) => <div key={i} className="h-20 bg-paper-200 dark:bg-ink-700 rounded-2xl"></div>)}
          </div>
        </div>
      </div>
    );
  }

  if (!stats) return null;

  // ✅ محافظت در برابر undefined — اگه فیلدی از API برنگشته، مقدار پیش‌فرض بده
  const safeStats = {
    online_now: stats.online_now || { total: 0, users: 0, guests: 0 },
    today: stats.today || { total: 0, users: 0, guests: 0, new: 0, returning: 0 },
    week: stats.week || { total: 0 },
    month: stats.month || { total: 0 },
    all_time: stats.all_time || { total: 0 },
    page_views_today: stats.page_views_today || 0,
    funnel: stats.funnel || [],
    top_pages: stats.top_pages || [],
    daily_series: stats.daily_series || [],
    device_breakdown: stats.device_breakdown || [],
    table_exists: stats.table_exists,
  };

  if (safeStats.table_exists === false) {
    return (
      <div className="bg-rose-50 dark:bg-rose-500/10 border border-rose-200 dark:border-rose-500/30 rounded-3xl p-4 text-center">
        <div className="text-2xl mb-2">⚠️</div>
        <p className="text-sm font-bold text-rose-700 dark:text-rose-300">
          جدول آمار ساخته نشده — python install_visitor_stats.py را اجرا کنید
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3 sm:space-y-4">
      {/* ===== هدر + ۴ کارت ===== */}
      <div className="bg-ink-900 dark:bg-ink-950 text-cream-100 rounded-3xl shadow-soft relative overflow-hidden">
        <div className="absolute -top-12 -left-12 w-40 h-40 bg-accent-500/10 rounded-full" aria-hidden="true" />
        <div className="absolute -bottom-16 -right-16 w-56 h-56 bg-brand-500/5 rounded-full" aria-hidden="true" />

        <div className="relative p-4 sm:p-5">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 sm:w-11 sm:h-11 rounded-2xl bg-brand-gradient flex items-center justify-center text-xl sm:text-2xl flex-shrink-0 shadow-brand" aria-hidden="true">
                📊
              </div>
              <div>
                <h2 className="font-display font-black text-base sm:text-lg tracking-tight">
                  آمار بازدیدکنندگان
                </h2>
                <p className="text-[10px] sm:text-[11px] text-cream-300/80 mt-0.5 flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-accent-400 animate-pulse" aria-hidden="true" />
                  <span>بازدیدکننده یکتا · آمار واقعی</span>
                </p>
              </div>
            </div>
            <div className="text-left">
              <div className="text-[10px] text-cream-400 font-bold">بازدید صفحه امروز</div>
              <div className="font-display font-black text-lg text-cream-50 font-num tabular-nums">
                {fmt(safeStats.page_views_today)}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
            <StatCard
              icon="🟢"
              label="آنلاین هم‌اکنون"
              value={fmt(safeStats.online_now.total)}
              sub={`${fmt(safeStats.online_now.users)} کاربر · ${fmt(safeStats.online_now.guests)} مهمان`}
              variant="online"
            />
            <StatCard
              icon="📅"
              label="بازدیدکننده امروز"
              value={fmt(safeStats.today.total)}
              sub={`${fmt(safeStats.today.new)} جدید · ${fmt(safeStats.today.returning)} بازگشتی`}
              variant="today"
            />
            <StatCard
              icon="📆"
              label="این هفته"
              value={fmt(safeStats.week.total)}
              sub="بازدیدکننده یکتا"
              variant="week"
            />
            <StatCard
              icon="🗓️"
              label="این ماه"
              value={fmt(safeStats.month.total)}
              sub={`کل: ${fmt(safeStats.all_time.total)}`}
              variant="month"
            />
          </div>
        </div>
      </div>

      {/* ===== قیف تبدیل + نمودار ===== */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-3 sm:gap-4">
        {/* قیف تبدیل */}
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
          <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-paper-100/50 dark:bg-ink-900/30">
            <div className="w-9 h-9 rounded-2xl bg-accent-100 dark:bg-accent-500/20 flex items-center justify-center text-lg flex-shrink-0 text-accent-700 dark:text-accent-300" aria-hidden="true">
              🎯
            </div>
            <div>
              <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
                قیف تبدیل مشتری
              </div>
              <div className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
                از ورود تا خرید — کجا منصرف می‌شن؟
              </div>
            </div>
          </div>
          <div className="p-4 sm:p-5">
            <ConversionFunnel stages={safeStats.funnel} />
          </div>
        </div>

        {/* نمودار ۷ روز */}
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
          <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-paper-100/50 dark:bg-ink-900/30">
            <div className="w-9 h-9 rounded-2xl bg-brand-100 dark:bg-brand-500/20 flex items-center justify-center text-lg flex-shrink-0 text-brand-700 dark:text-brand-300" aria-hidden="true">
              📈
            </div>
            <div>
              <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
                روند ۷ روز اخیر
              </div>
              <div className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
                بازدیدکننده یکتا — جدید و بازگشتی
              </div>
            </div>
          </div>
          <div className="p-4 sm:p-5">
            <WeeklyChart data={safeStats.daily_series} />
          </div>
        </div>
      </div>

      {/* ===== صفحات پربازدید + دستگاه ===== */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-3 sm:gap-4">
        {/* صفحات پربازدید */}
        <div className="lg:col-span-2 bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
          <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-paper-100/50 dark:bg-ink-900/30">
            <div className="w-9 h-9 rounded-2xl bg-brand-100 dark:bg-brand-500/20 flex items-center justify-center text-lg flex-shrink-0 text-brand-700 dark:text-brand-300" aria-hidden="true">
              📄
            </div>
            <div>
              <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
                صفحات پربازدید امروز
              </div>
              <div className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
                کجا رفتن؟
              </div>
            </div>
          </div>
          <div className="p-3 sm:p-4">
            {safeStats.top_pages.length > 0 ? (
              <div className="space-y-2">
                {safeStats.top_pages.map((p, i) => {
                  const maxVisitors = safeStats.top_pages[0]?.unique_visitors || 1;
                  const pct = (p.unique_visitors / maxVisitors) * 100;
                  return (
                    <div key={i} className="flex items-center gap-3">
                      <div className="w-6 h-6 rounded-lg bg-paper-100 dark:bg-ink-700 flex items-center justify-center text-[10px] font-black text-ink-500 dark:text-cream-400 flex-shrink-0 font-num">
                        {fmt(i + 1)}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex justify-between mb-1">
                          <span className="text-xs font-black text-ink-700 dark:text-cream-200 truncate">
                            {p.name}
                          </span>
                          <span className="text-xs font-black text-ink-800 dark:text-cream-100 font-num tabular-nums flex-shrink-0 ml-2">
                            {fmt(p.unique_visitors)} نفر
                          </span>
                        </div>
                        <div className="w-full bg-paper-100 dark:bg-ink-700 rounded-full h-1.5 overflow-hidden">
                          <div className="h-full bg-brand-gradient rounded-full transition-all duration-500" style={{ width: `${pct}%` }} />
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="text-center text-sm text-ink-400 dark:text-cream-500 py-4">
                <div className="text-3xl mb-1 opacity-50">📭</div>
                <div className="text-xs font-bold">هنوز داده‌ای ثبت نشده</div>
              </div>
            )}
          </div>
        </div>

        {/* دستگاه‌ها */}
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
          <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-paper-100/50 dark:bg-ink-900/30">
            <div className="w-9 h-9 rounded-2xl bg-accent-100 dark:bg-accent-500/20 flex items-center justify-center text-lg flex-shrink-0 text-accent-700 dark:text-accent-300" aria-hidden="true">
              📱
            </div>
            <div>
              <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
                دستگاه‌ها
              </div>
              <div className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
                امروز
              </div>
            </div>
          </div>
          <div className="p-4 space-y-3">
            {safeStats.device_breakdown.length > 0 ? (
              safeStats.device_breakdown.map((d, i) => {
                const total = safeStats.today.total || 1;
                const pct = ((d.count / total) * 100).toFixed(0);
                const icon = d.device === 'mobile' ? '📱' : d.device === 'tablet' ? '📲' : '💻';
                const label = d.device === 'mobile' ? 'موبایل' : d.device === 'tablet' ? 'تبلت' : 'دسکتاپ';
                return (
                  <div key={i}>
                    <div className="flex justify-between mb-1.5">
                      <span className="text-xs font-black text-ink-700 dark:text-cream-200 flex items-center gap-1.5">
                        <span>{icon}</span><span>{label}</span>
                      </span>
                      <span className="text-xs font-black font-num tabular-nums">
                        {fmt(d.count)} <span className="text-[10px] text-ink-400">({pct}%)</span>
                      </span>
                    </div>
                    <div className="w-full bg-paper-100 dark:bg-ink-700 rounded-full h-2 overflow-hidden">
                      <div className="h-full bg-brand-gradient rounded-full transition-all duration-700" style={{ width: `${pct}%` }} />
                    </div>
                  </div>
                );
              })
            ) : (
              <div className="text-center text-sm text-ink-400 py-3">
                <div className="text-xs font-bold">داده‌ای نیست</div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
